package main

import (
"context"
"fmt"
"log"

"github.com/ethereum/go-ethereum/ethclient"
)

func main() {
client, err := ethclient.Dial("http://127.0.0.1:8545")
if err != nil {
log.Fatal(err)
}

rawTx := ""

// We'll call SendRawTransaction manually, then immediately GetTransactionByHash
var txHash string
err = client.Client().CallContext(context.Background(), &txHash, "eth_sendRawTransaction", rawTx)
if err != nil {
log.Println("Send error:", err)
return
}
fmt.Println("Sent TX:", txHash)

var tx interface{}
err = client.Client().CallContext(context.Background(), &tx, "eth_getTransactionByHash", txHash)
if err != nil {
log.Println("Get error:", err)
} else {
fmt.Printf("Get result: %+v\n", tx)
}
}
